"""Original mission-led A2–B2 course drafts for adult French learners.

All passages, dialogues, examples, and exercises in this file are Parlez-authored.
The levels remain unpublished by default and still require qualified FLE review.
"""

from .types import (
    Course,
    DialogueLine,
    Exercise,
    GrammarExample,
    GrammarRule,
    Lesson,
    Unit,
    VocabItem,
)
from .mission_expansions import expand_mission_courses as _expand_mission_courses


def _mc(prompt, options, answer, explanation):
    return {
        "type": "multiple_choice",
        "prompt": prompt,
        "options": options,
        "answer": answer,
        "explanation": explanation,
    }


def _fill(prompt, answer, explanation, acceptable=None):
    return {
        "type": "fill_blank",
        "prompt": prompt,
        "answer": answer,
        "acceptable": acceptable or [],
        "explanation": explanation,
    }


def _translate(prompt, answer, explanation, acceptable=None):
    return {
        "type": "translate_to_fr",
        "prompt": prompt,
        "answer": answer,
        "acceptable": acceptable or [],
        "explanation": explanation,
    }


def _lesson(
    lesson_id,
    title,
    title_fr,
    description,
    objectives,
    skill_tags,
    transfer_task,
    vocabulary,
    grammar,
    dialogue,
    exercise_specs,
    self_check,
    *,
    exercise_prefix=None,
    cultural_note=None,
    minutes=30,
):
    prefix = exercise_prefix or lesson_id
    return Lesson(
        id=lesson_id,
        title=title,
        titleFr=title_fr,
        description=description,
        objectives=objectives,
        skillTags=skill_tags,
        transferTask=transfer_task,
        selfCheck=self_check,
        vocabulary=[
            VocabItem(fr=fr, en=en, category=category, example=example, exampleEn=example_en)
            for fr, en, category, example, example_en in vocabulary
        ],
        grammar=[
            GrammarRule(
                title=grammar[0],
                explanation=grammar[1],
                examples=[GrammarExample(fr=fr, en=en) for fr, en in grammar[2]],
                tip=grammar[3] if len(grammar) > 3 else None,
            )
        ],
        dialogue=[
            DialogueLine(speaker=speaker, name=name, fr=fr, en=en)
            for speaker, name, fr, en in dialogue
        ],
        exercises=[
            Exercise(id=f"{prefix}-e{index}", **spec)
            for index, spec in enumerate(exercise_specs, start=1)
        ],
        culturalNote=cultural_note,
        estimatedMinutes=minutes,
    )


def _unit(unit_id, title, title_fr, theme, description, outcomes, skill_tags, capstone, criteria, lessons):
    return Unit(
        id=unit_id,
        title=title,
        titleFr=title_fr,
        theme=theme,
        description=description,
        outcomes=outcomes,
        skillTags=skill_tags,
        capstone=capstone,
        capstoneCriteria=criteria,
        lessons=lessons,
    )


