                [("A", "Client", "Je prépare un repas pour trois personnes.", "I am preparing a meal for three people."), ("B", "Vendeuse", "Vous pouvez prendre ce paquet de riz. Il est moins cher.", "You can take this packet of rice. It is less expensive."), ("A", "Client", "Je ne trouve pas de tomates. Je peux les remplacer par quoi ?", "I cannot find tomatoes. What can I replace them with?"), ("B", "Vendeuse", "Des poivrons, si vous aimez leur goût.", "Peppers, if you like their flavour.")],
