                [("ça te dit de", "would you like to", "Invitations", "Ça te dit d'aller au cinéma ?", "Would you like to go to the cinema?"), ("avec plaisir", "with pleasure", "Responses", "Avec plaisir, merci !", "With pleasure, thank you!"), ("malheureusement", "unfortunately", "Responses", "Malheureusement, je travaille samedi.", "Unfortunately, I am working on Saturday."), ("plutôt", "rather / instead", "Preferences", "On peut se voir plutôt dimanche ?", "Could we meet on Sunday instead?"), ("convenir", "to suit / work for", "Scheduling", "Dix heures me conviennent.", "Ten o'clock works for me.")],
