                [("un programme", "a schedule / plan", "Planning", "Voici le programme de samedi.", "Here is Saturday's plan."), ("se retrouver", "to meet up", "Plans", "On se retrouve devant la gare.", "Let's meet in front of the station."), ("un billet", "a ticket", "Travel", "J'achète les billets en ligne.", "I am buying the tickets online."), ("réserver", "to reserve", "Planning", "Nous allons réserver une table.", "We are going to reserve a table."), ("le retour", "the return", "Travel", "Le retour est prévu à vingt heures.", "The return is planned for eight p.m.")],
                ("Linking a simple itinerary", "Use puis, ensuite, and enfin to make the order clear. Use aller + infinitive for planned actions and check that times do not conflict.", [("D'abord, on se retrouve à la gare, puis on prend le bus.", "First, we meet at the station, then we take the bus."), ("Ensuite, nous allons visiter le parc.", "Then, we are going to visit the park.")]),
                [("A", "Zoé", "On se retrouve à la gare à neuf heures ?", "Shall we meet at the station at nine?"), ("B", "Karim", "Oui. Le bus pour le parc part à neuf heures vingt.", "Yes. The bus for the park leaves at 9:20."), ("A", "Zoé", "Ensuite, on déjeune près du lac et on rentre à vingt heures.", "Then we have lunch near the lake and return at eight p.m."), ("B", "Karim", "Parfait. Je réserve une table pour treize heures.", "Perfect. I will reserve a table for one p.m.")],
